import numpy as np

def feature(moves, owner, homes, points, adjacency, turn):
    """Contested value (points/5 * min(opp_neighbours,3)/3) only when my score is not above the opponent's, else 0."""
    s_me = points[owner == 1].sum()
    s_op = points[owner == -1].sum()
    if s_me > s_op:
        return np.zeros(len(moves))
    opp = (owner == -1).astype(np.int32)
    opp_n = adjacency[moves].astype(np.int32) @ opp  # opponent neighbours per candidate
    return (points[moves] / 5.0) * (np.minimum(opp_n, 3) / 3.0)
